window.EXTRA_LABS={
fractions:{description:'Scegli due frazioni. I punti sulla linea dei numeri mostrano gli addendi e la loro somma; i denominatori sono sempre positivi.',controls:[['n1','Numeratore di A',-6,6,1,1],['d1','Denominatore di A',1,8,1,2],['n2','Numeratore di B',-6,6,1,1],['d2','Denominatore di B',1,8,1,3]]},
powers:{description:'Varia base ed esponente intero. Osserva il segno, il reciproco e i casi non definiti con base zero.',controls:[['base','Base',-3,3,1,2],['exponent','Esponente intero',-3,4,1,3]]},
balance:{description:'La curva blu è il primo membro ax + b; quella verde è il secondo membro c. Le intersezioni rappresentano le soluzioni.',controls:[['a','Coefficiente a',-4,4,1,2],['b','Termine b',-6,6,1,3],['c','Secondo membro c',-6,12,1,11]]},
quadratic:{description:'Cambia a, b e c. Le radici reali sono gli zeri del polinomio. Prova anche a = 0: il grado cambia.',controls:[['a','Coefficiente a',-3,3,1,1],['b','Coefficiente b',-6,6,1,-3],['c','Termine c',-6,6,1,2]]},
function:{description:'Muovi x per leggere f(x). Modificando i coefficienti cambi la funzione; il dominio di questi polinomi è tutto ℝ.',controls:[['a','Coefficiente di x²',-2,2,.5,1],['b','Coefficiente di x',-3,3,.5,0],['c','Termine costante',-4,4,1,1],['x','Ingresso x',-5,5,.25,2]]},
units:{description:'La velocità fisica resta la stessa: cambiano numero e unità. La barra confronta i valori numerici, non due velocità diverse.',controls:[['speed','Velocità in km/h',0,144,3.6,72]]},
vectors:{description:'Vettori di spostamento in metri. A è blu, B verde, A + B viola. B tratteggiato parte dalla punta di A.',controls:[['ax','Componente Ax (m)',-4,4,1,3],['ay','Componente Ay (m)',-4,4,1,0],['bx','Componente Bx (m)',-4,4,1,0],['by','Componente By (m)',-4,4,1,4]]},
uniform:{description:'Moto rettilineo a velocità costante. Il grafico rappresenta la posizione in funzione del tempo, da 0 a 5 s.',controls:[['x0','Posizione iniziale (m)',-10,10,1,2],['v0','Velocità (m/s)',-5,5,.5,3],['t','Tempo (s)',0,5,.1,2]]},
accelerated:{description:'Moto ideale con accelerazione costante per tutto l’intervallo. Confronta i grafici x(t) e v(t); un cambio di verso è ammesso.',controls:[['x0','Posizione iniziale (m)',-5,5,1,0],['v0','Velocità iniziale (m/s)',-5,5,1,4],['a','Accelerazione (m/s²)',-4,4,.5,-2],['t','Tempo (s)',0,5,.1,2]]},
fall:{description:'Asse y positivo verso l’alto; g = 9,81 m/s² costante, aria trascurata. L’avanzamento termina al primo arrivo al suolo.',controls:[['h','Altezza iniziale (m)',1,40,1,20],['v0','Velocità iniziale (m/s)',-10,20,1,0],['progress','Avanzamento del volo (%)',0,100,1,50]]}
};
function curvePlot(series,{xmin=-6,xmax=6,markerX=0,xlabel='x',ylabel='y'}={}){
 const W=600,H=300,left=60,right=25,top=25,bottom=42,steps=100;
 const samples=series.map(s=>Array.from({length:steps+1},(_,i)=>({x:xmin+(xmax-xmin)*i/steps,y:s.fn(xmin+(xmax-xmin)*i/steps)})));
 const ys=samples.flatMap(a=>a.map(p=>p.y));let low=Math.min(0,...ys),high=Math.max(0,...ys),span=Math.max(1,high-low);low-=span*.1;high+=span*.1;
 const X=x=>left+(x-xmin)/(xmax-xmin)*(W-left-right),Y=y=>H-bottom-(y-low)/(high-low)*(H-top-bottom);
 let svg=`<svg class="plot" viewBox="0 0 ${W} ${H}" role="img" aria-label="Grafico: asse orizzontale ${esc(xlabel)}, asse verticale ${esc(ylabel)}. Valori e risultati nel testo sottostante.">`;
 for(let i=0;i<=4;i++){const x=xmin+(xmax-xmin)*i/4,y=low+(high-low)*i/4;svg+=`<path d="M${X(x)} ${top}V${H-bottom}M${left} ${Y(y)}H${W-right}" stroke="var(--grid)" fill="none"/><text x="${X(x)}" y="${H-bottom+18}" text-anchor="middle">${fmt(x)}</text><text x="${left-7}" y="${Y(y)+4}" text-anchor="end">${fmt(y)}</text>`}
 svg+=`<path d="M${left} ${Y(0)}H${W-right}${xmin<=0&&xmax>=0?`M${X(0)} ${top}V${H-bottom}`:''}" stroke="var(--muted)" opacity=".6" fill="none"/>`;
 series.forEach((s,i)=>{svg+=`<path d="${samples[i].map((p,j)=>(j?'L':'M')+X(p.x)+' '+Y(p.y)).join(' ')}" fill="none" stroke="${s.color||'var(--blue)'}" stroke-width="2.5"/>`;if(markerX>=xmin&&markerX<=xmax)svg+=`<circle cx="${X(markerX)}" cy="${Y(s.fn(markerX))}" r="4" fill="${s.color||'var(--blue)'}"/>`});
 return svg+`<text x="${W-15}" y="${H-7}" text-anchor="end">${esc(xlabel)}</text><text x="${left}" y="15">${esc(ylabel)}</text></svg>`;
}
function realRoots(a,b,c){
 if(a===0)return b===0?{kind:c===0?'all':'none',roots:[]}:{kind:'linear',roots:[-c/b]};
 const delta=b*b-4*a*c;if(delta<0)return{kind:'none',roots:[],delta};
 if(delta===0)return{kind:'double',roots:[-b/(2*a)],delta};
 return{kind:'two',roots:[(-b-Math.sqrt(delta))/(2*a),(-b+Math.sqrt(delta))/(2*a)].sort((x,y)=>x-y),delta};
}
function gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){[a,b]=[b,a%b]}return a||1}
function numberLine(values){const max=Math.max(2,...values.map(v=>Math.abs(v.value)))*1.25,X=x=>300+x/max*265;return `<svg class="plot" viewBox="0 0 600 150" role="img" aria-label="Frazioni e somma sulla linea dei numeri"><path d="M25 85H575" stroke="var(--muted)"/>${[-max,0,max].map(x=>`<path d="M${X(x)} 80v10" stroke="var(--muted)"/><text x="${X(x)}" y="110" text-anchor="middle">${fmt(x)}</text>`).join('')}${values.map((p,i)=>`<circle cx="${X(p.value)}" cy="85" r="5" fill="${p.color}"/><text x="${X(p.value)}" y="${25+i*16}" text-anchor="middle" style="fill:${p.color}">${p.label} = ${fmt(p.value)}</text>`).join('')}</svg>`}
function drawExtraLab(type,z){const result=html=>`<div class="lab-result" aria-live="polite">${html}<small style="color:var(--muted);font-size:10px">Valori numerici arrotondati a tre decimali. I grafici di funzioni e tempo possono usare scale diverse sui due assi.</small></div>`;
 if(type==='fractions'){const n=z.n1*z.d2+z.n2*z.d1,d=z.d1*z.d2,k=gcd(n,d);return numberLine([{label:'A',value:z.n1/z.d1,color:'var(--blue)'},{label:'B',value:z.n2/z.d2,color:'var(--green)'},{label:'A + B',value:n/d,color:'var(--violet)'}])+result(fm(R`\frac{${z.n1}}{${z.d1}}+\frac{${z.n2}}{${z.d2}}=\frac{${n}}{${d}}=\frac{${n/k}}{${d/k}}`)+`<p>Il denominatore comune bd vale ${d}. Somma = ${fmt(n/d)}.</p>`)}
 if(type==='powers'){if(z.base===0&&z.exponent<=0)return result(z.exponent===0?'0⁰ non viene definito in questo percorso elementare.':'Zero con esponente negativo richiederebbe una divisione per zero: espressione non definita.');const value=z.base**z.exponent;return result(fm(R`(${z.base})^{${z.exponent}}=${z.exponent<0?R`\frac{1}{(${z.base})^{${-z.exponent}}}`:texnum(value)}`)+`<p>Valore ${z.exponent<0?'approssimato ':''}= ${fmt(value)}. ${z.exponent===0?'Per una base non nulla, l’esponente zero dà 1.':z.exponent<0?'L’esponente negativo indica il reciproco della potenza positiva.':'Il prodotto contiene '+z.exponent+' fattori uguali alla base.'}</p>`)}
 if(type==='balance'){let text;if(z.a===0)text=z.b===z.c?'Identità: tutti i numeri reali sono soluzioni. Le curve coincidono.':'Equazione impossibile: nessuna soluzione. Le curve sono parallele distinte.';else text=fm(R`x=\frac{${z.c}-(${z.b})}{${z.a}}`)+`<p>Soluzione x ≈ ${fmt((z.c-z.b)/z.a)}; entrambi i membri valgono ${fmt(z.c)}.</p>`;const root=z.a===0?0:(z.c-z.b)/z.a,extent=Math.max(6,Math.abs(root)+1);return curvePlot([{fn:x=>z.a*x+z.b},{fn:()=>z.c,color:'var(--green)'}],{xmin:-extent,xmax:extent,markerX:root})+result(text)}
 if(type==='quadratic'){const r=realRoots(z.a,z.b,z.c),extent=Math.max(6,...r.roots.map(x=>Math.abs(x)+1));const text=r.kind==='all'?'Ogni reale è soluzione: il polinomio è identicamente zero.':r.kind==='none'?'Nessuna soluzione reale.':r.kind==='double'?`Una soluzione reale doppia: x ≈ ${fmt(r.roots[0])}.`:`${r.kind==='linear'?'Equazione di primo grado':'Due soluzioni reali distinte'}: ${r.roots.map(x=>'x ≈ '+fmt(x)).join('; ')}.`;return curvePlot([{fn:x=>z.a*x*x+z.b*x+z.c}],{xmin:-extent,xmax:extent,markerX:r.roots[0]??0})+result((z.a!==0?fm(R`\Delta=${texnum(r.delta)}`)+'<p>':'<p>a = 0: il secondo grado scompare. ')+text+'</p>')}
 if(type==='function'){const y=z.a*z.x*z.x+z.b*z.x+z.c;return curvePlot([{fn:x=>z.a*x*x+z.b*x+z.c}],{markerX:z.x})+result(fm(R`f(x)=(${texnum(z.a)})x^2+(${texnum(z.b)})x+(${texnum(z.c)})`)+`<p>Ingresso x = ${fmt(z.x)} → uscita f(x) = ${fmt(y)}. Il punto (${fmt(z.x)}; ${fmt(y)}) appartiene al grafico.</p>`)}
 if(type==='units'){const ms=z.speed/3.6;return `<svg class="plot" viewBox="0 0 600 140" role="img" aria-label="Confronto tra i valori numerici della stessa velocità in km/h e m/s"><text x="25" y="25">${fmt(z.speed)} km/h</text><rect x="25" y="35" width="${z.speed/144*550}" height="18" rx="4" fill="var(--blue)"/><text x="25" y="85">${fmt(ms)} m/s</text><rect x="25" y="95" width="${ms/144*550}" height="18" rx="4" fill="var(--green)"/></svg>`+result(fm(R`${texnum(z.speed)}\,\mathrm{km/h}=${texnum(ms)}\,\mathrm{m/s}`)+`<p>In un secondo, mantenendo questa velocità, si percorrono ${fmt(ms)} m. Il valore in m/s è quello in km/h diviso per 3,6.</p>`)}
 if(type==='vectors'){const sx=z.ax+z.bx,sy=z.ay+z.by;return geometry({points:[{x:z.ax,y:z.ay,name:'A'},{x:z.bx,y:z.by,name:'B',color:'var(--green)'},{x:sx,y:sy,name:'R',color:'var(--violet)'}],segments:[{x1:0,y1:0,x2:z.ax,y2:z.ay,color:'var(--blue)',dash:'none'},{x1:0,y1:0,x2:z.bx,y2:z.by,color:'var(--green)',dash:'none'},{x1:z.ax,y1:z.ay,x2:sx,y2:sy,color:'var(--green)'},{x1:0,y1:0,x2:sx,y2:sy,color:'var(--violet)',dash:'none'}]})+result(fm(R`\mathbf R=(${sx},${sy})\,\mathrm m`)+`<p>|A| ≈ ${fmt(Math.hypot(z.ax,z.ay))} m; |B| ≈ ${fmt(Math.hypot(z.bx,z.by))} m; |R| ≈ ${fmt(Math.hypot(sx,sy))} m. ${sx===0&&sy===0?'Il risultante è nullo.':''}</p>`)}
 if(type==='uniform'||type==='accelerated'){const a=type==='uniform'?0:z.a,x=z.x0+z.v0*z.t+.5*a*z.t*z.t,v=z.v0+a*z.t;let html=curvePlot([{fn:t=>z.x0+z.v0*t+.5*a*t*t}],{xmin:0,xmax:5,markerX:z.t,xlabel:'t (s)',ylabel:'x (m)'});if(type==='accelerated')html+=curvePlot([{fn:t=>z.v0+a*t,color:'var(--green)'}],{xmin:0,xmax:5,markerX:z.t,xlabel:'t (s)',ylabel:'v (m/s)'});return html+result(`<p>t = ${fmt(z.t)} s · x = ${fmt(x)} m · v = ${fmt(v)} m/s · a = ${fmt(a)} m/s².</p><p>Spostamento dall’inizio: ${fmt(x-z.x0)} m. ${v*a<0?'In questo istante il modulo della velocità sta diminuendo.':v*a>0?'In questo istante il modulo della velocità sta aumentando.':a===0?'La velocità è costante.':'La velocità è momentaneamente nulla; l’accelerazione resta diversa da zero.'}</p>`)}
 if(type==='fall'){const g=9.81,end=(z.v0+Math.sqrt(z.v0*z.v0+2*g*z.h))/g,t=end*z.progress/100,y=Math.max(0,z.h+z.v0*t-.5*g*t*t),v=z.v0-g*t;return curvePlot([{fn:t=>Math.max(0,z.h+z.v0*t-.5*g*t*t)}],{xmin:0,xmax:end,markerX:t,xlabel:'t (s)',ylabel:'y (m)'})+result(`<p>t ≈ ${fmt(t)} s · y ≈ ${fmt(y)} m · vy ≈ ${fmt(v)} m/s.</p><p>Primo arrivo al suolo: t ≈ ${fmt(end)} s. ${z.progress===100?'Il modello termina qui, prima di descrivere l’urto.':v>0?'Il corpo sta salendo.':v<0?'Il corpo sta scendendo.':'Velocità momentaneamente nulla; accelerazione = −9,81 m/s².'}</p>`)}
 throw new Error('Laboratorio non riconosciuto: '+type);
}
